SELECT *
FROM b_didi_v5_colliding_data_log
WHERE id > #{lastId}
  AND result = 'true'
  AND create_time >= curdate()
  AND api_code = #{apiCode}
ORDER BY id ASC
    LIMIT #{pageSize}

SELECT distinct(cell) FROM b_didi_v5_colliding_data_log Where cell in
#{cell}
AND fail_reason in (2,3)

SELECT distinct(cell)
FROM b_didi_v5_colliding_data_log
Where cell in

    #{cell}

AND fail_reason in

    #{failMsg}
